'use strict';
/* Builds one self-contained file per partner function (for pasting into the Supabase dashboard editor or deploying as a single file).
   Run: node scripts/bundle-functions.js   ->  partners-backend/single-file/<function>.ts */
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..', 'partners-backend', 'supabase', 'functions');
const out = path.join(__dirname, '..', 'partners-backend', 'single-file');
fs.mkdirSync(out, { recursive: true });
const rd = (f) => fs.readFileSync(path.join(root, f), 'utf8');
const strip = (src) => src
  .replace(/^import .*\n/gm, '')
  .replace(/^export (async function|function|const|interface)/gm, '$1');
const util = strip(rd('_shared/util.ts')), email = strip(rd('_shared/email.ts'));
for (const fn of ['partner-portal', 'partner-admin-review', 'partner-apply', 'partner-click']) {
  const body = strip(rd(fn + '/index.ts')).replace(/^if \(import\.meta\.main\) Deno\.serve\(handle\);\s*$/m, 'Deno.serve(handle);');
  const needsMail = /sendEmail|Email\(/.test(body);
  const text = `// ${fn} - single-file version (generated by scripts/bundle-functions.js; the readable source is supabase/functions/)\nimport { createClient, type SupabaseClient } from "npm:@supabase/supabase-js@2";\n\n// ---- shared helpers ----\n${util}\n${needsMail ? '// ---- e-mail ----\n' + email + '\n' : ''}// ---- ${fn} ----\n${body}`;
  fs.writeFileSync(path.join(out, fn + '.ts'), text);
  console.log('wrote', fn + '.ts', text.length, 'bytes');
}
